gzP(){return"\u062a\u0639\u0630\u0651\u0631 \u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u0645\u0641\u0636\u0644\u0629. \u062a\u0623\u0643\u0651\u062f \u0645\u0646 \u0635\u062d\u0629 \u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0633\u0631\u064a \u0648\u0645\u0646 \u0623\u0646\u0643 \u0645\u0646\u062d\u062a LastStats \u0627\u0644\u0625\u0630\u0646 \u0639\u0644\u0649 Last.fm\u060c \u062b\u0645 \u062d\u0627\u0648\u0644 \u0645\u062c\u062f\u062f\u064b\u0627."},
gvt(){return"\u0645\u0641\u0627\u062a\u064a\u062d API"},
gpZ(){return"\u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0633\u0631\u064a"},
gvE(){return"\u063a\u064a\u0631 \u0645\u062d\u062f\u062f"},
gvx(){return"\u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0633\u0631\u064a \u064a\u062a\u064a\u062d \u0625\u0636\u0627\u0641\u0629 \u0623\u0648 \u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0645\u0642\u0637\u0648\u0639\u0627\u062a \u0645\u0646 \u0627\u0644\u0645\u0641\u0636\u0644\u0629 \u0645\u0628\u0627\u0634\u0631\u0629 \u0639\u0644\u0649 Last.fm."},
gvu(){return"\u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u0645\u0641\u0636\u0644\u0629"},
gvw(){return"\u0625\u0644\u063a\u0627\u0621 \u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u0645\u0641\u0636\u0644\u0629"},
gpm(){return"\u0627\u0644\u0645\u0641\u0636\u0644\u0629"},
gtE(){return"\u064a\u0639\u0631\u0636 \u0639\u062f\u062f \u0627\u0644\u0645\u0641\u0636\u0644\u0629 \u0641\u064a \u0627\u0644\u0625\u062d\u0635\u0627\u0626\u064a\u0627\u062a"},
gtD(){return"\u0623\u0636\u0641 \u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0633\u0631\u064a \u0641\u064a \u0627\u0644\u062d\u0633\u0627\u0628 \u0644\u0644\u062a\u0641\u0639\u064a\u0644"},
